\label{wandssolution}
		Let $T>0$ be a finite constant. A solution $(\rho,u, \Phi)$ to \eqref{origin} is called a weak solution if it satisfies \eqref{origin} in the sense of distributions. Moreover, if
		all the derivatives involved in \eqref{origin} are regular distributions and \eqref{origin} holds almost everywhere in $\Omega \times (0,T)$, the solution is called a strong solution.

\label{thm1}
		Let $\Omega$ be a simply connected bounded domain in $\mathbb{R}^2$ with $C^{2,1}$ boundary $\partial \Omega$. Assume that
		\begin{align}\label{betagamma}
			\beta > \frac{4}{3}, \quad \gamma >1,
		\end{align}
		and that the initial data $\rho_0 \geq 0$, $m_0$ and $\nabla \Phi_0$ satisfy, for some $q>2$,
		\begin{align}\label{initialcondition}
			\rho_0 \in W^{1,q}, \quad u_0 \in \tilde{H}^1, \quad \nabla \Phi_0 \in \tilde{W}^{2,q}, \quad m_0=\rho_0 u_0, \quad \Delta\Phi_0=\rho_0-b(x),
		\end{align}
		with $b(x) \in W^{1,q}$.
		
		Then the problem \eqref{origin}-\eqref{boundary2} has a unique strong solution $(\rho ,u,\nabla \Phi)$ in $\Omega \times (0,\infty)$ satisfying, for any $0<T< \infty$,
		\begin{equation}\label{theorem1}
			\left\{
			\begin{array}{lll}
				\rho \in C([0,T]; W^{1,q}), \quad \rho_{t} \in L^{\infty}(0,T;L^2),\\[2mm]
				\nabla \Phi \in C([0,T]; W^{2,q}), \quad \nabla \Phi_{t} \in L^{\infty}(0,T;H^1),\\[2mm]
				u \in L^{\infty}(0,T;H^1) \cap L^{1+\frac{1}{q}}(0,T; W^{2,q}),\\[2mm]
				\sqrt{t}u \in L^{\infty}(0,T;H^2) \cap L^{2}(0,T; W^{2,q}), \quad \sqrt{t}u_t \in L^2(0,T;H^1),\\[2mm]
				\rho u \in C([0,T];L^2), \quad \sqrt{\rho}u_t \in L^2((0,T)\times \Omega).
			\end{array}
			\right.
		\end{equation}

\label{thm2}
		Assume the conditions of Theorem \ref{thm1}, except that the requirements $\rho_0 \in W^{1,q}$ and $\nabla \Phi_0 \in \tilde{W}^{2,q}$ in \eqref{initialcondition} are replaced by $\rho_0 \in L^{\infty}$, and let $\Phi_0$ satisfy $\Delta \Phi_0 = \rho_0 - b(x)$ with $(\partial_n \Phi_0)|_{\partial \Omega}=0$. Then there exists at least one weak solution $(\rho ,u, \nabla \Phi)$ to the problem \eqref{origin}-\eqref{boundary2} in $\Omega \times (0,\infty)$ satisfying, for any $0<\tau \leq T< \infty$ and $p \geq 1$,
		\begin{equation}\label{theorem2}
			\left\{
			\begin{array}{lll}
				\rho \in L^{\infty}(0,T;L^{\infty}) \cap C([0,T];L^p), \quad \nabla \Phi \in L^{\infty}(0,T;L^{\infty}) \cap C([0,T];W^{1,p}) \\[2mm]
				u \in L^{\infty}(0,T;H^1), \quad u_t \in L^2(\tau,T; L^{2}), \quad \nabla u \in L^{\infty}(\tau,T; L^{p})\\[2mm]
				\mbox{curl} u, (2\mu + \lambda)\mbox{div}u - P \in  L^{2}(0,T;H^1) \cap L^{\frac{3}{2}}(0,T; L^{\infty}).
			\end{array}
			\right.
		\end{equation}
		
		
		Moreover, there exists a positive constant $C$ depending on $\Omega,T,\mu,\beta, \gamma,\|b(x)\|_{W^{1,q}}, \|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$ such that
		\begin{equation}\label{infrho}
			\inf_{(x,t)\in \Omega \times (0,T)} \rho(x,t) \geq C^{-1} \inf_{x\in \Omega } \rho_0(x).
		\end{equation}

\label{lem-localexistence}
		Assume that $(\rho_0,m_0,\Phi_0)$ satisfies
		\begin{align}\label{initialvalue}
			\rho_0 \in H^{2}, \quad \inf_{x\in \Omega }\rho_0(x)>0, \quad u_0 \in H^2 \cap \tilde{H}^1, \quad \nabla \Phi_0 \in H^3 \cap \tilde{W}^{2,q}, \quad m_0=\rho_0 u_0, \quad \Delta \Phi_0=\rho_0-b(x),
		\end{align}
		with $b(x) \in H^2$.
		
		Then there exist a sufficiently small time $T>0$ and a constant $C_0>0$, both depending only on $\Omega,\mu,\beta,\gamma,\|\rho_0\|_{H^2}$, $\|b(x)\|_{H^2}$, $\|u_0\|_{H^2}$, and $\inf_{x\in \Omega }\rho_0(x)$, such that the problem \eqref{origin}-\eqref{boundary2} has a unique strong solution $(\rho ,u,\nabla \Phi)$ in $\Omega \times (0, T)$ satisfying
		\begin{equation}\label{localexistence}
			\left\{
			\begin{array}{lll}
				\rho \in C([0,T]; H^2), \quad \rho_{t} \in C([0,T];H^1),\\[2mm]
				\nabla \Phi \in C([0,T]; H^3), \quad \nabla \Phi_{t} \in C([0,T];H^2),\\[2mm]
				u \in C([0,T];H^2)\cap L^{2}(0,T;H^3) , \quad u_t \in  C([0,T]; L^2) \cap L^{2}(0,T;H^1),\\[2mm]
				\rho u \in C([0,T];L^2), \quad \sqrt{\rho}u_t \in L^2((0,T)\times \Omega).
			\end{array}
			\right.
		\end{equation}
		and
		\begin{equation}\label{localinf}
			\inf_{(x,t)\in \Omega \times (0,T)} \rho(x,t) \geq C_0 >0.
		\end{equation}

\label{lem-div-curl}
		Let $\Omega$ be a domain in $\mathbb{R}^{2}$ with smooth boundary $\partial\Omega$ and outward normal $n$. Then there exists a constant $C>0$ such that
		\begin{equation}\label{A3-1}
			\|v\|_{H^{s}}\leq C\left(\|\mbox{div}v\|_{H^{s-1}}+\|\mbox{curl}v\|_{H^{s-1}}
			+ |v\cdot n|_{H^{s-\frac{1}{2}}(\partial\Omega)}+\|v\|_{L^2}\right),
		\end{equation}
		for any $v\in H^{s}(\Omega)$, $s\geq1$.

([\cite{wahl}, Theorem 3.2] and \cite{A2014, M2005, wahl})\label{lem-important}
		Let $1<p<\infty$ and $\Omega$ be a simply connected bounded domain in $\mathbb{R}^2$ with Lipschitz boundary $\partial \Omega$. Then there exists a positive constant $C$ depending only on $\Omega$ and $p$ such that every $v \in W^{1,p}$ with $v \cdot n=0$ on $\partial \Omega$ satisfies
		\begin{equation}\label{important}
			\|\nabla v\|_{L^p}\leq C\left(\|\mbox{div}v\|_{L^p}+\|\mbox{curl}v\|_{L^p}\right).
		\end{equation}

(see \cite{T1976})\label{lem-poincare}
		There exists a positive constant $C$ depending only on $\Omega$ such that every function $u \in H^1(\Omega)$ satisfies, for $2<p<\infty$,
		\begin{equation}\label{poincare}
			\|u\|_{L^p} \leq C p^{\frac{1}{2}} \|u\|^{\frac{2}{p}}_{L^2} \|u\|^{1-\frac{2}{p}}_{H^1},
		\end{equation}
		where $\|u\|_{H^1}$ can be replaced by $\|\nabla u\|_{L^2}$ provided that
		$$(u\cdot n)|_{\partial \Omega}=0 \quad \mbox{or} \quad \int_{\Omega} u \mbox{d} x=0.$$

\label{lem-poincare2}
		Let $\Omega \in \mathbb{R}^n$ be an open, bounded Lipschitz set. Then every $u \in W^{1,2}(\Omega)$ satisfying $u \cdot n=0$ on $\partial \Omega$ obeys
		\begin{equation}\label{poincare2}
			\|u\|_{L^2(\Omega)} \leq C(\Omega) \|\nabla u\|_{L^2},
		\end{equation}
		where the constant $C(\Omega)$ depends only on $\Omega$ (it is independent of $u$).

(see \cite{CL2023})\label{lem-boundary-key}
		Assume that $\Omega$ is a bounded $C^{2,1}$ domain in $\mathbb{R}^2$. Let $v, f \in H^{1}$ with $v\cdot n=0$ on $\partial\Omega$. Then
		\begin{align}
			\left|\int_{\partial\Omega}v\cdot\nabla f\right|\leq C\|v\|_{H^1}\| f\|_{H^1}.\nonumber
		\end{align}

(see \cite{CL2023, BKM1984})\label{lem-nablau}
		For $2<q<\infty$, there is a constant $C$ depending only on $\Omega$ and $q$ such that every $u \in \{ W^{2,q}(\Omega)| u \cdot n=0, \mbox{curl} u = -Au \cdot n^{\bot} \quad on \quad \partial \Omega \}$ satisfies
		\begin{equation}\label{nablerho}
			\|\nabla u \|_{L^{\infty}} \leq C( \|\mbox{div}u\|_{L^{\infty}} + \|\mbox{curl} u\|_{L^{\infty}} )\log (e+ \|\nabla^2 u\|_{L^q}) + C \|\nabla u\|_{L^2} +C.
		\end{equation}

\label{theorem-trace}
		Let $f \in H^{m_1} (\Omega) \cap H^{m_2} (\Omega)$ and $\triangledown f \in H^{m_2} (\Omega)$. Then
		
		\begin{equation}\label{2eq2-3}
			|f|^2_{H^s(\partial \Omega)} \leq C(\|\nabla f\|_{H^{m_2}} + \|f\|_{H^{m_2}}) \| f\|_{H^{m_1}},
		\end{equation}
		where $m_1+ m_2 \geq 2s \geq 0$ and $m_1$, $m_2$ are nonnegative integers.

(\cite{FLL2022})\label{lem-conformal}
		Let $n$ be the outward unit normal vector to $\partial \Omega$ at $x_0$. Then
		\begin{equation}\label{conformal}
			n \cdot \nabla \psi(x_0)=|\nabla \psi_1(x_0)|n,
		\end{equation}
		where $n$ is the outward unit normal vector to $\partial \mathbb{D}$ at $\psi(x_0)$.

\label{lem1}
		There exists a positive constant $C$ depending only on $\gamma$, $\|\rho_0\|_{L^{\gamma} \cap L^2}$, $\|b(x)\|_{L^2}$, and $\|\sqrt{\rho_0} u_0\|_{L^2}$ such that
		\begin{align}\label{lem1-1}
			& \sup_{0 \leq t \leq T} \int_{\Omega} ( \rho |u|^2 + \rho^{\gamma} + |\nabla \Phi|^2 ) \mbox{d}x + \int_{0}^{T} \int_{\Omega}( (2 \mu + \lambda)|\mbox{div}u|^2+ \mu |\omega|^2 )\mbox{d}x \mbox{d}t \leq C.
		\end{align}

A direct calculation shows that
		\begin{equation}\label{1-1}
			P_t + \mbox{div}(Pu) + (\gamma-1) P \mbox{div}u=0,
		\end{equation}
	by $\eqref{origin}^1$. Integrating with respect to $x$ and then integrating by parts, using the boundary condition \eqref{boundary1}, namely $(u \cdot n)|_{\partial \Omega}=0$, we obtain
	\begin{equation}\label{1-2}
		\frac{d}{dt} \int_{\Omega} \frac{\rho^{\gamma}}{\gamma-1} \mbox{d}x + \int_{\Omega} P\mbox{div}u\mbox{d}x =0.
	\end{equation}
	
	Recall that
	$$\rho u_t + \rho (u \cdot \nabla )u + \nabla P= \nabla ( (2\mu + \lambda(\rho)) \mbox{div}u )+ \mu \nabla^{\bot} \omega + \rho \nabla \Phi.$$
	
	Taking the inner product with $u$ and integrating with respect to $x$, we obtain
	\begin{align}\label{1-3}
		&\int_{\Omega}( \rho u_t \cdot u + \rho (u \cdot \nabla )u \cdot u+ \nabla P\cdot u) \mbox{d}x = \int_{\Omega}(\nabla ( (2\mu + \lambda(\rho)) \mbox{div}u )\cdot u+ \mu \nabla^{\bot} \omega \cdot u + \rho \nabla \Phi \cdot u) \mbox{d}x .
	\end{align}
	
	We have the vector calculus identities
	\begin{equation}\label{vector-1}
		\nabla \cdot (\mbox{div}u u)= |\mbox{div}u|^2+ \nabla \mbox{div}u \cdot u,
	\end{equation}
	and
	\begin{equation}\label{vector-2}
		\nabla^{\bot } \cdot (\omega u  )= |\omega|^2 + \nabla^{\bot} \omega \cdot u.
	\end{equation}
	
	Integrating by parts, applying the boundary conditions, and using $\eqref{origin}^1$ and \eqref{1-2} in \eqref{1-3}, we obtain
	\begin{align}\label{1-4}
		&\int_{\Omega}( \frac{\partial }{\partial t} (\frac{1}{2} \rho |u|^2)+ \frac{\partial}{\partial t}\frac{\rho^{\gamma}}{\gamma-1}) \mbox{d}x = \int_{\Omega}(\nabla ( (2\mu + \lambda(\rho)) \mbox{div}u )\cdot u+ \mu \nabla^{\bot} \omega \cdot u + \rho \nabla \Phi \cdot u) \mbox{d}x \nonumber\\[2mm]
		& = \int_{\Omega}(- (2\mu + \lambda(\rho)) |\mbox{div}u|^2 - \mu | \omega|^2 - \Phi\mbox{div}(\rho u)) \mbox{d}x - \mu \int_{\partial\Omega} A|u|^2 \mbox{d}s \nonumber\\[2mm]
		& = \int_{\Omega}(- (2\mu + \lambda(\rho)) |\mbox{div}u|^2 - \mu | \omega|^2 + \Phi \Delta\Phi_t) \mbox{d}x - \mu \int_{\partial\Omega} A|u|^2 \mbox{d}s \nonumber\\[2mm]
		& = \int_{\Omega}(- (2\mu + \lambda(\rho)) |\mbox{div}u|^2 - \mu | \omega|^2 -\frac{\partial}{\partial t}\frac{1}{2}|\nabla \Phi|^2) \mbox{d}x- \mu \int_{\partial\Omega} A|u|^2 \mbox{d}s ,
	\end{align}
	where we have used $\eqref{origin}^1$ and $\eqref{origin}^3$ to obtain $\mbox{div}(\rho u)=-\rho_t= (-b(x)-\Delta \Phi)_t= -\Delta\Phi_t$, together with the boundary conditions \eqref{boundary1}, with $A$ positive on the boundary, and $(\nabla \Phi \cdot n)|_{\partial \Omega}=0$.
	
	Integrating with respect to $t$ completes the proof.

\label{lem2}
    	Let $\beta > \frac{4}{3}$. Then, for any $1 \leq p < \infty$, there is a constant $C$ depending on $\Omega$, $T$, $\mu$, $\beta$, $\gamma$, $\|b(x)\|_{L^{\infty}}$, $\|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$ such that
    	\begin{equation}\label{lem2-rho}
    		\sup_{0 \leq t \leq T}\|\rho(t)\|_{L^p} \leq C(T) p^{\frac{2}{\beta-1}},
    	\end{equation}
    	and
    	\begin{equation}\label{lem2-phi}
    		\sup_{0 \leq t \leq T}\|\nabla \Phi(t) \|_{L^p} \leq C(T) p^{\frac{2}{\beta-1}},
    	\end{equation}
    	Here and below, $C$ denotes a generic positive constant depending on $\Omega$, $T$, $\mu$, $\beta$, $\gamma$, $\|b(x)\|_{L^{\infty}}$, $\|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$; we write $C(\alpha)$ to indicate that $C$ also depends on $\alpha$.

\label{elliptic}
    		
    		There exists a constant $C_\Omega$ depending only on $\Omega$ such that:
    		
    		\begin{enumerate}
    			\item If $1<a\le2$, then
    			\begin{equation}\label{hessian}
    				\lVert D^2\mathcal N f\rVert_{L^a}\le {C_\Omega\over a-1}\lVert f\rVert_{L^a}.
    			\end{equation}
    			\item If $z$ is the zero-mean weak solution of
    			\[
    			\int_\Omega\nabla z\cdot\nabla\varphi
    			=\int_\Omega v\cdot\nabla\varphi\qquad(\varphi\in H^1(\Omega)),
    			\]
    			then for $2\le a<\infty$,
    			\begin{equation}\label{projection}
    				\lVert \nabla z\rVert_{L^a}\le C_\Omega a\lVert v\rVert_{L^a}.
    			\end{equation}
    			Equivalently, this corresponds to
    			\[
    			\Delta z=\operatorname{div} v,\qquad \partial_n z=v\cdot n
    			\]
    			in the weak sense.
    			\item The zero-mean Neumann Green function, with sign convention
    			$\Delta_yN(x,y)=\delta_x(y)-|\Omega|^{-1}$, satisfies
    			\begin{equation}\label{green-gradient}
    				|\nabla_yN(x,y)|\le {C_\Omega\over |x-y|}\quad(x\ne y).
    			\end{equation}
    		\end{enumerate}

