\label{lem5}
    	For $p>2$ and $\epsilon>0$, there exists some positive constant $C(p,\epsilon)$	depending only on $p$, $\epsilon$, and $\Omega$ such that
    	\begin{equation}\label{lem5-1}
    		\|\nabla u\|_{L^p} \leq C(p,\epsilon)R_T^{\frac{1}{2}-\frac{1}{p}+\epsilon}A_1 \left( \frac{A^2_2}{A_1^2} \right)^{\frac{1}{2}-\frac{1}{p}} + C(p,\epsilon)R_T^{\epsilon}A_1.
    	\end{equation}

First, we rewrite the momentum equations as
    	\begin{equation}\label{5-1}
    		\rho \dot{u} =\nabla F + \mu \nabla^{\bot}\omega + \rho \nabla \Phi,
    	\end{equation}
    	which, together with the boundary conditions \eqref{boundary1} and \eqref{boundary2}, shows that $F$ solves the Neumann problem:
    	\begin{equation}\label{5-2}
    		\left\{
    		\begin{array}{lll}
    			\Delta F = \mbox{div}( \rho (\dot{u} - \nabla \Phi)), \quad \mbox{in} \,\Omega\\[2mm]
    			\frac{\partial F}{\partial n} = \rho \dot{u} \cdot n - \mu n^{\bot} \cdot \nabla ( A u \cdot n^{\bot}) - \rho \nabla \Phi \cdot n =- \rho (u \cdot \nabla) n \cdot u - \mu \partial_{\tau}(Au_{\tau}), \quad \mbox{on} \, \partial \Omega,
    		\end{array}
    		\right.
    	\end{equation}
    	and that $\omega$ solves the related Dirichlet problem:
    	\begin{equation}\label{omega}
    		\left\{
    		\begin{array}{lll}
    			\mu \Delta \omega = \nabla^{\bot}\cdot (\rho (\dot{u} - \nabla \Phi) ), \quad \mbox{in} \,\Omega\\[2mm]
    			\omega= -A u \cdot n^{\bot}, \quad \mbox{on} \, \partial \Omega,
    		\end{array}
    		\right.
    	\end{equation}
    	The standard $L^p$ estimates for elliptic equations (\cite{GT1983}, [\cite{NS2004}, Lemma 4.27]) then imply that, for $k \geq 0$ and $p \in (1,\infty)$,
    	\begin{equation}\label{5-3}
    		\|\nabla F\|_{W^{k,p}} + \|\nabla \omega\|_{W^{k,p}} \leq C(p,k,\Omega)( \|\rho (\dot{u}-\nabla \Phi)\|_{W^{k,p}} + \|\nabla u\|_{W^{k,p}} ).
    	\end{equation}
    	
    	In particular, we have
    	\begin{equation}\label{5-4}
    		\|\nabla F\|_{L^2} + \|\nabla \omega\|_{L^2} \leq C( \|\rho (\dot{u}-\nabla \Phi)\|_{L^2} + \|\nabla u\|_{L^2} ) \leq CR_T^{\frac{1}{2}}A_2 + CA_1,
    	\end{equation}
    	which, together with the Poincar\'{e} inequality (Lemma \ref{lem-poincare2}) and Lemma \ref{lem2}, yields
    	\begin{equation}\label{5-5}
    		\| F\|_{H^1} + \| \omega\|_{H^1} \leq C(\|\nabla F\|_{L^2} + \|(\nabla \omega,\omega)\|_{L^2} )+ \frac{C}{|\Omega|}\int_{\Omega}F \mbox{d}x \leq CR_T^{\frac{1}{2}}A_2 + CA_1.
    	\end{equation}
    	
    	Applying Lemma \ref{lem-div-curl} and the estimate for $\rho$ in Lemma \ref{lem2}, we obtain
    	\begin{align}\label{5-6}
    		\|\nabla u\|_{L^p} &\leq C(p)( \|\mbox{div}u\|_{L^p} + \|\omega\|_{L^p} )\nonumber\\[2mm]
    		&\leq C(p)( \|\frac{F}{2 \mu + \lambda(\rho)}\|_{L^p} + \|\omega\|_{L^p} )+ C(p)\nonumber\\[2mm]
    		& \leq C(p)( \|\frac{F}{2 \mu + \lambda(\rho)}\|_{L^2}^{\frac{2}{p}-\epsilon}\|F\|_{H^1}^{-\frac{2}{p}+1-\epsilon} + \|\omega\|_{L^2}^{\frac{2}{p}}\|\omega\|_{H^1}^{1-\frac{2}{p}}  )+C(p)\nonumber\\[2mm]
    		& \leq  C(p)( A_1^{\frac{2}{p}-\epsilon}\|F\|_{L^2}^{\epsilon}\|F\|_{H^1}^{1-\frac{2}{p}+1} + A_1^{\frac{2}{p}}\|\omega\|_{H^1}^{1-\frac{2}{p}}  )+C(p)\nonumber\\[2mm]
    		& \leq C(p,\epsilon)R_T^{\frac{\beta\epsilon}{2}}A_1^{\frac{2}{p}}( \|F\|_{H^1}+ \|\omega\|_{H^1})^{1-\frac{2}{p}} +C(p),
    	\end{align}
    	where, in the third inequality, we have used Lemma \ref{lem-poincare} to estimate $\|\frac{F}{2 \mu + \lambda(\rho)}\|_{L^p}$ and $\|\omega\|_{L^p}$.
    	
    	Combining \eqref{5-5} and \eqref{5-6}, we complete the proof.

\label{lem6}
         For any $\alpha\in (0,1)$, there is a constant $C(\alpha)$ depending only on $\alpha$, $\Omega$, $T$, $\mu$, $\beta$, $\gamma$, $\|b(x)\|_{L^{\infty}}$, $\|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$ such that
         \begin{equation}\label{lem6-1}
         	\sup_{0 \leq t \leq T} \log A^2_1(t) + \int_{0}^{T} \frac{A_2^2(t)}{A_1^2(t)} \mbox{d}t \leq C(\alpha)R_T^{1+\alpha}.
         \end{equation}

We modify the ideas of \cite{FLL2022,HL2016} to overcome the difficulties arising from the boundary. First, direct calculations show that
    	\begin{equation}\label{6-1}
    		\nabla^{\bot}\cdot \tilde{u} = \nabla^{\bot}\cdot \dot{u} - \nabla^{\bot }\cdot \nabla \Phi= \frac{D}{Dt}\omega - (\partial_1 u \cdot \nabla)u_2 + (\partial_2 u \cdot \nabla)u_1= \frac{D}{Dt}\omega + \omega \mbox{div}u,
    	\end{equation}
    	and that
    	\begin{align}\label{6-2}
    		&\mbox{div}\tilde{u}= \mbox{div}\dot{u}- \Delta\Phi= \frac{D}{Dt}\mbox{div}u + (\partial_1 u \cdot \nabla )u_1 + (\partial_2 u \cdot \nabla)u_2- \Delta \Phi\nonumber\\[2mm]
    		&= \frac{D}{Dt}( \frac{F}{2\mu + \lambda(\rho)} )+ \frac{D}{Dt}( \frac{P}{2\mu + \lambda(\rho)} )- 2 \nabla u_1 \cdot \nabla^{\bot }u_2 + |\mbox{div} u|^2- \Delta\Phi.
    	\end{align}
    	
    	Multiplying
    	\begin{equation}\label{6-3}
    		\rho \tilde{u}= \nabla F + \mu \nabla^{\bot}\omega
    	\end{equation}
    	by $2\tilde{u}$, integrating over $\Omega$, and using \eqref{6-1}, \eqref{6-2}, and the boundary condition \eqref{boundary1}, we obtain
    	\begin{align}\label{6-4}
    		&2 A^2_2= \int_{\Omega} 2 \rho |\tilde{u}|^2 \mbox{d}x= \int_{\Omega} 2\nabla F\cdot \tilde{u}+ 2\mu \nabla^{\bot} \omega \cdot \tilde{u} \mbox{d}x\nonumber\\[2mm]
    		&= \int_{\Omega} (-2F\mbox{div}\tilde{u} -2\mu \nabla^{\bot}\cdot \tilde{u} \omega )\mbox{d}x + \int_{\partial\Omega} (2 F \tilde{u} \cdot n + 2 \mu \omega ( \tilde{u} \cdot n^{\bot} )) \mbox{d} s\nonumber\\[2mm]
    		&= -\frac{d}{dt} \int_{\Omega} (\frac{|F|^2}{2\mu + \lambda{\rho}} + \mu |\omega|^2)\mbox{d}x - \int_{\Omega} (2F(u \cdot \nabla)(\frac{F}{2\mu +\lambda(\rho)}) +2F \frac{D}{Dt}(\frac{P}{2\mu + \lambda(\rho)})  \nonumber\\[2mm]
    		& -4F\nabla u_1 \cdot\nabla^{\bot}u_2 + 2F|\mbox{div}u|^2 - 2F\Delta\Phi +2\mu (u\cdot \nabla) \omega \omega + 2\mu |\omega|^2\mbox{div}u )\mbox{d}x + \int_{\partial\Omega} (2 F \tilde{u} \cdot n + 2 \mu \omega ( \tilde{u} \cdot n^{\bot} )) \mbox{d} s \nonumber\\[2mm]
    		&= -\frac{d}{dt} \int_{\Omega} (\frac{|F|^2}{2\mu + \lambda{\rho}} + \mu |\omega|^2)\mbox{d}x - \mu\int_{\Omega}|\omega|^2\mbox{div}u \mbox{d}x + 4\int_{\Omega} F \nabla u_1 \cdot \nabla^{\bot}u_2 \mbox{d}x- \int_{\Omega}2F|\mbox{div}u|^2\mbox{d}x\nonumber\\[2mm]
    		&  - \int_{\Omega} \frac{(\beta-1)\lambda(\rho)-2\mu}{(2\mu +\lambda)^2}F^2\mbox{div}u\mbox{d}x - 2\beta \int_{\Omega} \frac{\lambda(\rho)P}{(2\mu + \lambda(\rho))^2}F\mbox{div}u \mbox{d}x + 2\gamma\int_{\Omega} \frac{P}{2 \mu +\lambda(\rho)} F \mbox{div}u \mbox{d}x\nonumber\\[2mm]
    		&+ 2\int_{\Omega}F \Delta\Phi\mbox{d}x + \int_{\partial\Omega} (-2 F u \cdot \nabla n \cdot u + 2 \mu \omega ( \tilde{u} \cdot n^{\bot} )) \mbox{d} s =: - \frac{d}{dt}A_1^2+ \frac{d}{dt} \int_{\partial\Omega} A |u|^2 \mbox{d}s + \sum_{i=1}^{9}I_i. 
    	\end{align}
    	
    	Using Lemma \ref{lem-poincare}, \eqref{4-1}, and H$\ddot{o}$lder's inequality, we estimate $I_1$ as follows:
    	\begin{equation}\label{6-5}
    		I_1 \leq C\|\omega\|^2_{L^4}\|\mbox{div}u\|_{L^2}\leq C\|\omega\|_{L^2}\|\nabla \omega\|_{L^2}A_1\leq CA_1^2\|\nabla\omega\|_{L^2}.
    	\end{equation}
    	
    	
    	Similarly, choosing $p \geq \frac{8\beta}{\alpha}$, we obtain
    	\begin{align}\label{6-6}
    		|I_2|+|I_3|&\leq C\|F\|_{L^p}\|\nabla u\|_{L^2}^{\frac{2(p-3)}{p-2}}\|\nabla u\|_{L^p}^{\frac{2}{p-2}}\nonumber\\[2mm]
    		&\leq C\|F\|_{L^2}^{\frac{2}{p}}\|F\|_{H^2}^{1-\frac{2}{p}}A_1^{\frac{2(p-3)}{p-2}}\left( R_T^{\frac{\beta\epsilon}{2}}A_1^{\frac{2}{p}}( \|F\|_{H^1}+ \|\omega\|_{H^1})^{1-\frac{2}{p}} +1  \right)^{\frac{2}{p-2}}\nonumber\\[2mm]
    		& \leq C(\alpha) R_T^{\frac{\alpha\beta}{2}}( \|F\|_{H^1}+ \|\omega\|_{H^1} ) A_1^2 + C(\alpha)A_1^2,
    	\end{align}
    	where we have used \eqref{5-6} to estimate $\|\nabla u\|_{L^p}$ in the first line and the definitions of $R_T$ and $A_1$ to obtain $\|F\|_{L^2}\leq CR_T^{\frac{\beta}{2}}A_1$.
    	
    	The next four terms are estimated by the same arguments, using the bound $\|\rho\|_{L^p}\leq C$ from Lemma \ref{lem2} and the boundedness of $b(x)$:
    	\begin{align}\label{6-7}
    		\sum_{i=4}^{7} &\leq C \int_{\Omega}\frac{F^2|\mbox{div}u|}{2\mu +\lambda{\rho}}\mbox{d}x + C \int_{\Omega}\frac{P}{2\mu + \lambda(\rho)}|F||\mbox{div}u|\mbox{d}x + C\|F\|_{L^{3}}\|\Delta\Phi\|_{L^{\frac{3}{2}}} \nonumber\\[2mm]
    		&\leq CA_1\|\frac{F^2}{2\mu +\lambda{\rho}}\|_{L^2} + CA_1\|F\|_{L^{2+\frac{4\gamma}{\beta}}} + C\|F\|_{L^{3}}( 1+\|\rho\|_{L^{\frac{3}{2}}} )\nonumber\\[2mm]
    		& \leq CA_1\|\frac{F}{(2\mu +\lambda{\rho})^{\frac{1}{2}}}\|_{L^2}^{1-\alpha}\|F\|^{1+\alpha}_{L^{\frac{2(1+\alpha)}{\alpha}}} + C(\alpha)A_1\|F\|_{H^1} \nonumber\\[2mm]
    		& \leq C(\alpha)A_1^{2-\alpha}\|F\|^{\alpha}_{L^2}\|F\|_{H^1} + C(\alpha)A_1\|F\|_{H^1}\nonumber\\[2mm]
    		& \leq C(\alpha)R_T^{\frac{\alpha\beta}{2}}A_1^2\|F\|_{H^1},
    	\end{align}
    	where $0<\alpha<1$.
    	
    	Applying the trace theorem (Lemma \ref{theorem-trace}), Lemma \ref{lem-poincare2}, and Lemma \ref{lem-div-curl}, we obtain
    	\begin{equation}\label{6-8}
    		|I_8| \leq C \|F\|_{H^1}\|u\|^2_{H^1}\leq C\|F\|_{H^1}\|\nabla u\|_{L^2}^2\leq C\|F\|_{H^1}A_1^2.
    	\end{equation}
    	
    	For $I_9$, we have
    	\begin{align}\label{6-8-1}
    		I_9 &= 2 \mu \int_{\partial\Omega} \omega (\tilde{u} \cdot n^{\bot}) \mbox{d}s = - 2 \mu \int_{\partial \Omega} (A (u \cdot n^{\bot}) \frac{d}{dt} (u \cdot n^{\bot}) + A (u \cdot n^{\bot}) (u \cdot \nabla)u \cdot n^{\bot} + A (u \cdot n^{\bot}) \nabla \Phi \cdot n^{\bot} ) \mbox{d} s \nonumber\\[2mm]
    		& = - \mu \frac{d}{dt} \int_{\partial\Omega} A (u \cdot n^{\bot})^2 \mbox{d} s - 2 \mu \int_{\partial\Omega} (A (u \cdot n^{\bot})^2 (n^{\bot} \cdot \nabla) u \cdot n^{\bot} + A (u \cdot n^{\bot}) \nabla \Phi \cdot n^{\bot} ) \mbox{d} s \nonumber\\[2mm]
    		& = - \mu \frac{d}{dt} \int_{\partial\Omega} A |u|^2 \mbox{d} s - 2 \mu \int_{\partial\Omega} (\frac{1}{3}A (n^{\bot} \cdot \nabla)(u \cdot n^{\bot})^3 + A (u \cdot n^{\bot})^2 (n^{\bot} \cdot \nabla) n^{\bot} \cdot u + A (u \cdot n^{\bot}) \nabla \Phi \cdot n^{\bot} ) \mbox{d} s \nonumber\\[2mm]
    		& \leq - \mu \frac{d}{dt} \int_{\partial\Omega} A |u|^2 \mbox{d} s - 2 \mu \int_{\Omega} \frac{1}{3} \mbox{div}(A \nabla^{\bot} (u \cdot n^{\bot})^3) \mbox{d} x- C(\|\nabla u\|^3_{L^{2}}+\|\rho\|^2_{L^2}+1) \nonumber\\[2mm]
    		& \leq - \mu \frac{d}{dt} \int_{\partial\Omega} A |u|^2 \mbox{d} s + C \int_{\Omega} |\nabla u||u|^2 \mbox{d} x- C(\|\nabla u\|^3_{L^{2}}+\|\rho\|^2_{L^2}+1) \nonumber\\[2mm]
    		& \leq - \mu \frac{d}{dt} \int_{\partial\Omega} A |u|^2 \mbox{d} s + C A^3_1.
    	\end{align}
    	
    	
    	Substituting the estimates \eqref{6-5}-\eqref{6-8-1} into \eqref{6-4}, we obtain, for any $\alpha \in (0,1)$,
    	\begin{align}\label{6-9}
    		\frac{d}{dt}A^2_1(t)+ A_2^2(t) &\leq C(\alpha)R_T^{\frac{\alpha\beta}{2}}( \|F\|_{H^1}+\|\omega\|_{H^1} )A^2_1+C(\alpha)A_1^2\nonumber\\[2mm]
    		&\leq C(\alpha)R_T^{\frac{1+\alpha\beta}{2}}A_2A_1^2+C(\alpha)A_1^3\nonumber\\[2mm]
    		&\leq C(\alpha)R_T^{1+\alpha\beta}A_1^4 + \frac{1}{2} A_2^2,
    	\end{align}
    	where, in the second inequality, we have used \eqref{5-5} to estimate $\|F\|_{H^1}+\|\omega\|_{H^1}$. Combining this with \eqref{4-2}, which gives $\int_{0}^{T}A_1^2\mbox{d}t\leq C$, proves \eqref{lem6-1} and completes the proof of Lemma \ref{lem6}.

\label{lem7}
    	Let $n$ be the outward unit normal at $y_0\in \partial \Omega$, and let $\tilde{N}=\tilde{N}(x,y)$ be defined by \eqref{tildeN}. Then
    	\begin{equation}\label{lem7-1}
    	     \frac{\partial \tilde{N}}{\partial n}(x,y_0) = - \frac{1}{2\pi}| \nabla \psi_1(y_0)|.
    	\end{equation}

\label{lem8}
    	Let $F \in C^1(\bar{\Omega}) \cap C^2(\Omega)$ solve the problem \eqref{5-2}. Then, for $x \in \Omega$,
    	\begin{align}\label{lem8-1}
    		F(x) &= \int_{\Omega} \nabla_y \tilde{N}(x,y) \cdot \rho \tilde{u}(y) \mbox{d}y - \int_{\partial\Omega} \frac{\partial \tilde{N}}{\partial n}(x,y)F(y) \mbox{d}S_y \nonumber\\[2mm]
    		& - \mu \int_{\partial\Omega} \tilde{N}(x,y) n^{\bot}\cdot \nabla (Au\cdot n^{\bot}) \mbox{d}S_y.
    	\end{align}

Write $\tilde{N}(x,y)=N_1(x,y)+N_2(x,y)$, where
    	\begin{equation}\label{8-1}
    		N_1(x,y)= -\frac{1}{2\pi} \log|\psi(x)-\psi(y)|,
    	\end{equation}
    	and
    	\begin{equation}\label{8-2}
    		N_2(x,y)= -\frac{1}{2\pi} \log\left| |\psi(x)| \psi(y)- \frac{\psi(x)}{|\psi(x)|}\right|.
    	\end{equation}
    	
    	By Lemma \ref{lem-cauchy-riemann}, conformal mappings preserve harmonicity, so $N_2(x,\cdot)$ is harmonic in $\Omega$. Since $N_2(x,\cdot)$ has no singularities in $\Omega$, we may apply Green's second identity to $F$ and $N_2(x,\cdot)$ in $\Omega$ to obtain
    	\begin{equation}\label{8-3}
    		- \int_{\Omega} N_2 \Delta F \mbox{d}y = \int_{\partial\Omega} ( \frac{\partial N_2}{\partial n}F -N_2 \frac{\partial F}{\partial n} ) \mbox{d}S_y,
    	\end{equation}
    	where we have integrated by parts twice.
    	
    	Applying Green's second identity to $F$ and $N_1(x,\cdot)$ in $\Omega \backslash \tilde{B_r}(x)$, where $\tilde{B_r}(x)=\psi^{-1}(B_r(\psi(x)))$ is the inverse image under $\psi$ of the ball centered at $\psi(x)$ with radius $r$, we obtain, for sufficiently small $r$,
    	\begin{align}\label{8-4}
    		&\int_{\Omega \backslash \tilde{B_r}(x)} ( \Delta N_1 F -N_1 \Delta F ) \mbox{d}y\nonumber\\[2mm]
    		& = \int_{\partial\Omega}( \frac{\partial N_1}{\partial n}F -N_1 \frac{\partial F}{\partial n} ) \mbox{d}S_y - \int_{\partial \tilde{B_r}(x)} (\frac{\partial N_1}{\partial n}F -N_1 \frac{\partial F}{\partial n} ) \mbox{d}S_y.
    	\end{align}
    	
    	Letting $r \to 0$ and using the fact that $\Delta N_1=0$ in $\Omega \backslash \tilde{B_r}(x)$, we have
    	\begin{align}\label{8-5}
    		&-\int_{\Omega} N_1 \Delta F \mbox{d}y = \int_{\partial\Omega}( \frac{\partial N_1}{\partial n}F -N_1 \frac{\partial F}{\partial n} ) \mbox{d}S_y -\lim_{r\to 0} \int_{\partial \tilde{B_r}(x)} (\frac{\partial N_1}{\partial n}F -N_1 \frac{\partial F}{\partial n} ) \mbox{d}S_y.
    	\end{align}
    	
    	For sufficiently small $r$,
    	\begin{align}\label{8-6}
    		& | \int_{\partial \tilde{B_r}(x)} N_1 \frac{\partial F}{\partial n} \mbox{d} S_y| \leq \int_{\partial \tilde{B_r}(x)}|N_1(x,y)|\mbox{d}S_y \cdot \sup_{\partial \tilde{B_r}(x)} |\nabla F| \nonumber\\[2mm]
    		& \leq \int_{\partial B_r( \psi(x))} | \log|\psi(x)-\psi(y)|| \frac{1}{\nabla \psi_1(y)} \mbox{d}S_{\psi(y)} \cdot \sup_{\partial \tilde{B_r}(x)} |\nabla F| \nonumber\\[2mm]
    		& \leq Cr |\log r|\cdot \sup_{\partial \tilde{B_r}(x)}|\nabla \psi_1|^{-1} \sup_{\partial \tilde{B_r}(x)}|\nabla F| \to 0 \quad \mbox{as} \quad r \to 0,
    	\end{align}
    	and
    	\begin{align}\label{8-7}
    		&\int_{\partial \tilde{B_r}(x)} F \frac{\partial N_1}{\partial n} \mbox{d}S_y = \int_{\partial \tilde{B_r}(x)} n_y \cdot \nabla_y N_1(x,y) F(y)\mbox{d}S_y \nonumber\\[2mm]
    		& = - \frac{1}{2\pi} \int_{\partial \tilde{B_r}(x)} \frac{\nabla \psi(y)[\psi(y)-\psi(x)]}{|\nabla \psi_1(y)||\psi(x)-\psi(y)|} \cdot \frac{\nabla \psi(y)[\psi(x)-\psi(y)]}{|\psi(x)-\psi(y)|^2} F(y) \mbox{d}S_y \nonumber\\[2mm]
    		& = -\frac{1}{2\pi r} \int_{\partial \tilde{B_r}(x)} |\nabla \psi_1(y)|F(y) \mbox{d}S_y= -\frac{1}{2\pi r}  \int_{\partial B_r( \psi(x))} F( \psi^{-1}(\tilde{y})) \mbox{d}S_{\tilde{y}} \to - F(x) \quad \mbox{as} \quad r \to 0,
    	\end{align}
    	where we have used \eqref{psi_1} and the argument in \cite{FLL2022}, Lemma 3.6. Adding \eqref{8-3} and \eqref{8-5} and using \eqref{8-6} and \eqref{8-7}, we obtain
    	\begin{align}\label{8-8}
    		-F(x) &= \int_{\Omega} \tilde{N}(x,y) \mbox{div}(\rho \tilde{u})(y) \mbox{d}y+ \int_{\partial\Omega} \frac{\partial \tilde{N}}{\partial n}(x,y)F(y) \mbox{d}S_y - \int_{\partial\Omega} \tilde{N}(x,y)(\rho \tilde{u} \cdot n(y)-\mu n^{\bot} \cdot \nabla (Au\cdot n^{\bot}) )\mbox{d}S_y\nonumber\\[2mm]
    		& = - \int_{\Omega} \nabla_y \tilde{N}(x,y) \cdot \rho \tilde{u}(y) \mbox{d}y + \int_{\partial\Omega} \frac{\partial \tilde{N}}{\partial n}(x,y)F(y) \mbox{d}S_y+ \mu \int_{\partial\Omega} \tilde{N}(x,y) n^{\bot}\cdot \nabla (Au\cdot n^{\bot}) \mbox{d}S_y,
    	\end{align}
    	which yields \eqref{lem8-1} and completes the proof of Lemma \ref{lem8}.

\label{lem9}
    	For $J_1$ as in \eqref{J1}, there exists a generic positive constant $C(\Omega)$ such that for any $x \in \Omega$ with $\psi(x) \neq 0$,
    	\begin{align}\label{lem9-1}
    		|J_1(x)| &\leq C(\Omega) \int_{\Omega} \frac{\rho |u|^2(y)}{|x-y|} \mbox{d}y + C(\Omega) \int_{\Omega} \frac{|u(x)-u(y)|}{|x-y|^2}\rho |u|(y) \mbox{d}y \nonumber\\[2mm]
    		&+ C(\Omega) \int_{\Omega} \frac{|u(x')-u(y)|}{|x'-y|^2}\rho |u|(y) \mbox{d}y,
    	\end{align}
    	where
    	\begin{equation}\label{lem9-2}
    		x':= \psi^{-1}\left( \frac{\psi(x)}{|\psi(x)|} \right) \in \partial \Omega.
    	\end{equation}

\label{lem10}
    	For any $\epsilon>0$, we have
    	\begin{equation}\label{lem10-1}
    		\int_{0}^{T} \max_{x \in \bar{\Omega}} \int_{\Omega} \frac{|u(x)-u(y)|}{|x-y|^2}\rho |u|(y) \mbox{d}y \mbox{d}t \leq C(\epsilon)R_T^{1+\frac{\beta}{4}+3\epsilon}.
    	\end{equation}

First, let $2<p<4$ be chosen later. By the Sobolev embedding theorem (Theorem 5 of [\cite{E2010}, Chapter 5]), we have, for any $x,y \in \bar{\Omega}$,
    	\begin{equation}\label{10-1}
    		|u(x)-u(y)| \leq C(p) \|\nabla u\|_{L^p} |x-y|^{1-\frac{2}{p}},
    	\end{equation}
    	which implies
    	\begin{equation}\label{10-2}
    		\int_{\Omega} \frac{|u(x)-u(y)|}{|x-y|^2}\rho |u| (y)\mbox{d}y \leq C(p) \|\nabla u\|_{L^p} \int_{\Omega} |x-y|^{-(1+\frac{2}{p})} \rho |u|(y)\mbox{d}y.
    	\end{equation}
    	
    	Let $\delta>0$ and $\epsilon_0 \in (0,\frac{p-2}{8})$ be chosen later. On the one hand, H$\ddot{o}$lder's inequality and Lemma \ref{lem-poincare} give
    	\begin{align}\label{10-3}
    		& \int_{|x-y|<2 \delta} |x-y|^{-(1+\frac{2}{p})} \rho |u|(y)\mbox{d}y \leq C(p) R_T ( \int_{|x-y|<2 \delta} |x-y|^{-(1+\frac{2}{p})(1+\epsilon_0)} \mbox{d}y)^{\frac{1}{1+\epsilon_0}} \|u\|_{L^{\frac{1+\epsilon_0}{\epsilon_0}}}\nonumber\\[2mm]
    		& \leq C(p) R_T \delta^{1-\frac{2}{p}- \frac{2\epsilon_0}{1+\epsilon_0}} ( \frac{1+\epsilon_0}{\epsilon_0} )^{\frac{1}{2}} \|u\|_{H^1} \leq C(p) R_T \epsilon_0^{-\frac{1}{2}} A_1 \delta^{1-\frac{2}{p}- \frac{2\epsilon_0}{1+\epsilon_0}},
    	\end{align}
    	where we have used \eqref{4-1} to estimate $\|u\|_{H^1}$.
    	
    	On the other hand, for $\nu = R_T^{-\frac{\beta}{2}}\nu_0$ as defined in \eqref{lem4-2}, another application of H$\ddot{o}$lder's inequality, together with Lemma \ref{lem4}, gives
    	\begin{align}\label{10-4}
    		&\int_{|x-y|> \delta} |x-y|^{-(1+\frac{2}{p})} \rho |u|(y)\mbox{d}y\nonumber\\[2mm]
    		&\leq C(p) \left( \int_{|x-y|> \delta} |x-y|^{-(1+\frac{2}{p})(\frac{2+\nu}{1+\nu})} \mbox{d}y \right)^{\frac{1+\nu}{2+\nu}}\left( \int_{\Omega} \rho^{2+\nu}|u|^{2+\nu}\right)^{\frac{1}{2+\nu}} \leq C(p) R_T^{\frac{1+\nu}{2+\nu}}\delta^{-\frac{2}{p}+\frac{\nu}{2+\nu}},
    	\end{align}
    	since the definition of $R_T$ gives
    	$$\left( \int_{\Omega} \rho^{2+\nu} |u|^{2+\nu} \right)^{\frac{1}{2+\nu}} \leq R_T^{\frac{1+\nu}{2+\nu}} \left( \int_{\Omega} \rho |u|^{2+\nu} \right)^{\frac{1}{2+\nu}} \leq CR_T^{\frac{1+\nu}{2+\nu}}.$$
    	
    	Now, we choose $\delta>0$ such that
    	\begin{equation}\label{10-5}
    		\delta^{-\frac{2}{p}+\frac{\nu}{2+\nu}}= A_1^{\frac{2}{p}},
    	\end{equation}
    	which implies
    	\begin{equation}\label{10-6}
    		A_1\delta^{1-\frac{2}{p}- \frac{2\epsilon_0}{1+\epsilon_0}}= A_1^{\frac{2}{p}},
    	\end{equation}
    	provided we set
    	\begin{equation}\label{10-7}
    		\epsilon_0= \frac{(p-2)\nu}{8+(6-p)\nu} \in (0,\frac{p-2}{8}),
    	\end{equation}
    	where we used $\nu \in (0,1)$ and $2<p<4$.
    	
    	Then, it follows from \eqref{10-3}-\eqref{10-6} that
    	\begin{align}\label{10-8}
    		& \int_{\Omega} |x-y|^{-(1+\frac{2}{p})} \rho |u|(y)\mbox{d}y \leq C(p) R_T \epsilon_0^{-\frac{1}{2}}A_1^{\frac{2}{p}}+ C(p)R_T^{\frac{1+\nu}{2+\nu}}A_1^{\frac{2}{p}}\nonumber\\[2mm]
    		& \leq C(p)R_T^{1+\frac{\beta}{4}}A_1^{\frac{2}{p}},
    	\end{align}
    	where, in the last line, we have used $\epsilon_0^{-\frac{1}{2}}\leq C(p)\nu^{-\frac{1}{2}}\leq C(p)R_T^{\frac{\beta}{4}}$, which follows from the definition of $\epsilon_0$ and the identity $\nu=R_T^{-\frac{\beta}{2}}\nu_0$, with $\nu_0$ a small constant in $(0,1)$.
    	
    	Combining \eqref{10-8}, \eqref{10-2}, and Lemma \ref{lem5} shows that for any $\epsilon>0$,
    	\begin{align}\label{10-9}
    		& \int_{\Omega} \frac{|u(x)-u(y)|}{|x-y|^2}\rho |u| (y)\mbox{d}y \leq C(p) \|\nabla u\|_{L^p}R_T^{1+\frac{\beta}{4}}A_1^{\frac{2}{p}}\nonumber\\[2mm]
    		& \leq R_T^{1+\frac{\beta}{4}}A_1^{\frac{2}{p}}\left(C(p,\epsilon)R_T^{\frac{1}{2}-\frac{1}{p}+\epsilon}A_1 \left( \frac{A^2_2}{A_1^2} \right)^{\frac{1}{2}-\frac{1}{p}} + C(p,\epsilon)R_T^{\epsilon}A_1\right)\nonumber\\[2mm]
    		& \leq C(p,\epsilon) R_T^{\frac{3}{2}-\frac{1}{p}+\epsilon+\frac{\beta}{4}}A_1^{1+\frac{2}{p}} \left( \frac{A^2_2}{A_1^2} \right)^{\frac{1}{2}-\frac{1}{p}} + C(p,\epsilon)R_T^{1+\epsilon+\frac{\beta}{4}}A_1^{1+\frac{2}{p}}.
    	\end{align}
    	
    	Finally, integrating with respect to $t$ and applying H$\ddot{o}$lder's inequality, we obtain
    	\begin{align}\label{10-10}
    		& \int_{0}^{T} \max_{x \in \bar{\Omega}} \int_{\Omega} \frac{|u(x)-u(y)|}{|x-y|^2}\rho |u|(y) \mbox{d}y \mbox{d}t\nonumber\\[2mm]
    		& \leq C(p,\epsilon)R_T^{\frac{3}{2}-\frac{1}{p}+\epsilon+\frac{\beta}{4}} \left( \int_{0}^{T}A_1^2\mbox{d}t\right)^{\frac{1}{2}+\frac{1}{p}}\left( \int_{0}^{T} \frac{A_2^2}{A_1^2}\mbox{d}t\right)^{\frac{1}{2}-\frac{1}{p}} +C(p,\epsilon)R_T^{1+\epsilon+\frac{\beta}{4}} \left( \int_{0}^{T}A_1^2\mbox{d}t\right)^{\frac{1}{2}+\frac{1}{p}}\nonumber\\[2mm]
    		& \leq C(p,\epsilon) R_T^{2-\frac{2}{p}+2\epsilon+\frac{\beta}{4} },
    	\end{align}
    	where, in the last line, we have used \eqref{4-2} to estimate $\int_{0}^{T}A_1^2\mbox{d}t$ and Lemma \ref{lem6} to estimate $\int_{0}^{T} \frac{A_2^2}{A_1^2}\mbox{d}t$. Choosing $p=\frac{2}{1-\epsilon}$ yields \eqref{lem10-1} and completes the proof of Lemma \ref{lem10}.

\label{lem11}
    	Assume that \eqref{betagamma} holds. Then there exists some positive constant $C$ depending only on $\Omega,T,\mu,\beta, \gamma$, $\|b(x)\|_{L^{\infty}}$, $\|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$ such that
    	\begin{equation}\label{lem11-1}
    		\sup_{0 \leq t \leq T}( \|\rho \|_{L^{\infty}}+ \|u\|_{H^1}) + \int_{0}^{T} ( \|\omega\|_{H^1}^2 + \|F\|_{H^1}^2 + \|\sqrt{\rho}\dot{u}\|^2_{L^2} ) \mbox{d}t \leq C.
    	\end{equation}

For $\theta(\rho)$ defined in \eqref{theta}, equations \eqref{origin}, \eqref{Fdefinition}, and \eqref{omegadefinition} give
    	\begin{equation}\label{11-1}
    		\frac{D}{Dt} \theta(\rho) = - 2\mu \mbox{div}u - \rho^{\beta}\mbox{div}u = -(2\mu + \lambda{\rho})\mbox{div}u = -F-P \leq -F,
    	\end{equation} 
    	where we used that $P=\rho^{\gamma}\geq 0$.
    	
    	This, together with Lemma \ref{lem8}, \eqref{J}, \eqref{F-boundaryestimate}, and Lemma \ref{lem9}, gives
    	\begin{align}\label{11-2}
    		\frac{D}{Dt} \theta(\rho) & \leq -\frac{D}{Dt} \int_{\Omega} \partial_{y_j} \tilde{N}(x,y) \rho u_j(y) \mbox{d}y + \max_{x \in \bar{\Omega}} | \int_{\partial\Omega} \frac{\partial \tilde{N}}{\partial n} (x,y) F(y) \mbox{d}S_y| \nonumber\\[2mm]
    		&+ \max_{x \in \bar{\Omega}} |\int_{\partial\Omega} \tilde{N}(x,y) n^{\bot}\cdot \nabla (Au\cdot n^{\bot}) \mbox{d}S_y| + |J_1|+|J_2|\nonumber\\[2mm]
    		& \leq  -\frac{D}{Dt} \int_{\Omega} \partial_{y_j} \tilde{N}(x,y) \rho u_j(y) \mbox{d}y + \max_{x \in \bar{\Omega}} | \int_{\partial\Omega} \frac{\partial \tilde{N}}{\partial n} (x,y) F(y) \mbox{d}S_y|\nonumber\\[2mm]
    		&+ \max_{x \in \bar{\Omega}} |\int_{\partial\Omega} \tilde{N}(x,y) n^{\bot}\cdot \nabla (Au\cdot n^{\bot}) \mbox{d}S_y| +\max_{x \in \bar{\Omega}} \int_{\Omega} \frac{\rho |u|^2(y)}{|x-y|} \mbox{d}y \nonumber\\[2mm]
    		& + \max_{x \in \bar{\Omega}} \int_{\Omega} \frac{|u(x)-u(y)|}{|x-y|^2}\rho |u|(y) \mbox{d}y + \max_{x \in \bar{\Omega}} | \int_{\Omega} \partial_{y_j} \tilde{N}(x,y) \rho \partial_{y_j}\Phi \mbox{d}y|.
    	\end{align}
    	
    	On the one hand, a direct calculation gives, for $\nu = R_T^{-\frac{\beta}{2}}$ as in Lemma \ref{lem4},
    	\begin{align}\label{11-3}
    		& | \int_{\Omega} \partial_{y_j} \tilde{N}(x,y) \rho u_j(y) \mbox{d}y| \leq C \int_{\Omega} |x-y|^{-1} \rho (y) |u(y)| \mbox{d}y\nonumber\\[2mm]
    		& \leq C ( \int_{\Omega} |x-y|^{-\frac{2+\nu}{1+\nu}} \mbox{d}y)^{\frac{1+\nu}{2+\nu}}( \int_{\Omega} \rho^{2+\nu} |u|^{2+\nu} \mbox{d}y)^{\frac{1}{2+\nu}} \leq C \nu^{-\frac{1+\nu}{2+\nu}}R_T^{\frac{1+\nu}{2+\nu}}(\int_{\Omega} \rho |u|^{2+\nu} \mbox{d}y)^{\frac{1}{2+\nu}}\nonumber\\[2mm]
    		& \leq C R_T^{(1+\frac{\beta}{2})\frac{1+\nu}{2+\nu}} \leq C R_T^{\frac{2+\beta}{3}},
    	\end{align}
    	where the first inequality follows from the definition of $\tilde{N}$ and Lemma \ref{lem-cauchy-riemann}. We use H$\ddot{o}$lder's inequality in the second line, the arguments in \eqref{10-3} and \eqref{10-4} in the third line, and \eqref{lem4-1} in the last inequality.
    	
    	Similarly, one obtains
    	\begin{align}\label{11-4}
    		& | \int_{\Omega} \partial_{y_j} \tilde{N}(x,y) \rho \partial_{y_j}\Phi \mbox{d}y| \leq  C R_T^{\frac{2+\beta}{3}},
    	\end{align}
    	where we used Lemma \ref{lem2}.
    	
    	On the other hand, Sobolev's inequality leads to
    	\begin{equation}\label{11-5}
    		\int_{\Omega} \frac{\rho |u|^2(y)}{|x-y|} \mbox{d}y \leq R_T( \int_{\Omega} |x-y|^{-\frac{3}{2}} \mbox{d}y )^{\frac{2}{3}}( \int_{\Omega} |u|^6\mbox{d} y)^{\frac{1}{3}} \leq CR_T\|u\|^2_{H^1},
    	\end{equation}
    	which, together with \eqref{4-1} for $\|u\|_{H^1}$ and Lemma \ref{lem1}, gives
    	\begin{equation}\label{11-6}
    		\int_{0}^{T} \max_{x \in \bar{\Omega}}\int_{\Omega} \frac{\rho |u|^2(y)}{|x-y|} \mbox{d}y \mbox{d}t \leq C R_T. 
    	\end{equation}
    	
    	Finally, integrating \eqref{11-2} with respect to $t$ and using \eqref{F-boundaryestimate-2} for the boundary term, Lemma \ref{lem10}, \eqref{11-3}, \eqref{11-4}, and \eqref{11-6}, we obtain
    	\begin{equation}\label{11-7}
    		R_T^{\beta} \leq C(\epsilon) R_T^{\max\{1+\frac{\beta}{4}+3\epsilon,\frac{2+\beta}{3},1+\epsilon\}}.
    	\end{equation}
    	
    	Since $\beta> \frac{4}{3}$, this in particular implies by choosing $\epsilon>0$ sufficiently small
    	\begin{equation}\label{11-8}
    		\sup_{0 \leq t \leq T} \|\rho\|_{L^{\infty}} \leq C,
    	\end{equation}
    	which, together with \eqref{6-9}, \eqref{4-2}, \eqref{5-5}, and Gronwall's inequality, completes the proof of Lemma \ref{lem11}.

\label{lem12}
    	For $p \geq 1$, there exist positive constants $C_1(p,\Omega)$ and $C_2(\Omega)$ such that
    	\begin{equation}\label{lem12-1}
    		\|\dot{u}\|_{L^p} \leq C_1 ( \|\nabla \dot{u}\|_{L^2} + \|\nabla u\|_{L^2}^2 ),
    	\end{equation}
    	\begin{equation}\label{lem12-2}
    		\|\tilde{u}\|_{L^p} \leq C_1 ( \|\nabla \dot{u}\|_{L^2} + \|\nabla u\|_{L^2}^2 +1),
    	\end{equation}
    	and
    	\begin{equation}\label{lem12-3}
    		\|\nabla \dot{u}\|_{L^2} \leq C_2( \|\mbox{div}\dot{u}\|_{L^2} + \|\mbox{curl}\dot{u}\|_{L^2} + \|\nabla u\|_{L^4}^2 ),
    	\end{equation}
    	\begin{equation}\label{lem12-4}
    		\|\nabla \tilde{u}\|_{L^2} \leq C_2( \|\mbox{div}\dot{u}\|_{L^2} + \|\mbox{curl}\dot{u}\|_{L^2} + \|\nabla u\|_{L^4}^2 +1).
    	\end{equation}

First, by the definition $n^{\bot}=(n_2,-n_1)$ and the boundary condition $(u\cdot n)|_{\partial \Omega}=0$, we have
    	\begin{equation}\label{12-1}
    		u= ( u \cdot n^{\bot} )n^{\bot} \quad \mbox{on} \quad \partial \Omega,
    	\end{equation}
    	Thus, on the boundary $\partial \Omega$,
    	\begin{equation}\label{12-2}
    		\dot{u} \cdot n = (u\cdot \nabla )u \cdot n= - (u \cdot \nabla )n \cdot u = -(u \cdot n^{\bot})( u \cdot \nabla )n \cdot n^{\bot}= (u \cdot n^{\bot})(u \cdot \nabla)n^{\bot} \cdot n,
    	\end{equation}
    	which gives
    	\begin{equation}\label{12-3}
    		(\dot{u} - (u \cdot n^{\bot})(u \cdot \nabla)n^{\bot})\cdot n=0.
    	\end{equation}
    	
    	Applying \eqref{12-3} and Poincar\'{e}'s inequality (Lemma \ref{lem-poincare}), we obtain
    	\begin{equation}\label{12-4}
    		\|\dot{u} - (u \cdot n^{\bot})(u \cdot \nabla)n^{\bot}\|_{L^{\frac{3}{2}}} \leq C\|\nabla(\dot{u} - (u \cdot n^{\bot})(u \cdot \nabla)n^{\bot})\|_{L^{\frac{3}{2}}},
    	\end{equation}
    	and hence
    	\begin{equation}\label{12-5}
    		\|\dot{u} \|_{L^{\frac{3}{2}}} \leq C( \|\nabla \dot{u}\|_{L^{\frac{3}{2}}} + \|\nabla u\|_{L^2}^2 ),
    	\end{equation}
    	where we used
    	\begin{equation}\label{12-6}
    		\|(u \cdot n^{\bot})(u \cdot \nabla)n^{\bot}\|_{L^{\frac{3}{2}}} \leq C \|u\|_{L^3}^2\leq C(\|u\|_{L^2}^2 + \|\nabla u\|_{L^2}^2) \leq C \|\nabla u\|_{L^2}^2,
    	\end{equation}
    	by Lemma \ref{lem-poincare} and Lemma \ref{lem-poincare2}. Similarly, the same argument and H$\ddot{o}$lder's inequality give $\|\nabla((u \cdot n^{\bot})(u \cdot \nabla)n^{\bot})\|_{L^{\frac{3}{2}}} \leq C\|\nabla u\|_{L^2}\|u\|_{L^6}\leq C\|\nabla u\|_{L^2}^2$.
    	
    	Combining this with the Sobolev embedding theorem, we obtain, for $p \geq 1$,
    	\begin{align}\label{12-7}
    		\|\dot{u}\|_{L^p} &\leq C( \|\dot{u}\|_{L^2} + \|\nabla \dot{u}\|_{L^2} )\nonumber\\[2mm]
    		& \leq C ( \|\dot{u} \|_{L^{\frac{3}{2}}} + \|\nabla \dot{u}\|_{L^{\frac{3}{2}}}) + C\|\nabla \dot{u}\|_{L^2} \leq C( \|\nabla \dot{u} \|_{L^2} + \|\nabla u\|_{L^2}^2),
    	\end{align}
    	which completes the proof of \eqref{lem12-1}.
    	
    	Similarly, Lemma \ref{lem2} gives
    	\begin{align}\label{12-8}
    		\|\tilde{u}\|_{L^p} &\leq C( \|\dot{u}\|_{L^p} + \|\nabla \Phi\|_{L^p} )\nonumber\\[2mm]
    		& \leq C( \|\nabla \dot{u} \|_{L^2} + \|\nabla u\|_{L^2}^2+1),
    	\end{align}
    	which is \eqref{lem12-2}.
    	
    	Finally, \eqref{lem12-3} follows directly from \eqref{12-3} and Lemma \ref{lem-div-curl}. The proof is completed by combining \eqref{lem12-3} with
       	\begin{equation}\label{12-9}
    		\|\nabla \tilde{u}\|_{L^2} \leq C( \|\nabla \dot{u}\|_{L^2} + \|\Delta\Phi\|_{L^2} )
    	\end{equation}
    	where $\|\Delta \Phi\|_{L^2} \leq C(\|\rho\|_{L^2}+1)\leq C$ follows from the estimates for $\rho$ and $b(x)$.

\label{lem13}
    	There is a positive constant $C$ depending only on  $\Omega,T,\mu,\beta, \gamma$, $\|b(x)\|_{L^{\infty}}$, $\|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$ such that
    	\begin{equation}\label{lem13-1}
    		\sup_{0 \leq t \leq T} \sigma \int_{\Omega} \rho |\tilde{u}|^2 \mbox{d}x + \int_{0}^{T} \sigma \|\nabla \tilde{u}\|^2_{L^2} \mbox{d}t \leq C,
    	\end{equation}
    	with $\sigma(t):= \min \{ 1,t\}$. Moreover, for any $p\in [1,\infty)$, there is a positive constant $C(p)$ depending only on  $p,\Omega,T,\mu,\beta, \gamma, \|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$ such that
    	\begin{equation}\label{lem13-2}
    		\sup_{0 \leq t \leq T} \sigma \|\nabla u\|_{L^p}^2 \leq C(p).
    	\end{equation}

\label{lem14}
    	Assume that \eqref{betagamma} holds. Then for any $p>2$, there is a positive constant $C$ depending only on $\Omega,p,T,\mu,\beta, \gamma$, $\|b(x)\|_{L^{\infty}}$, $\|\rho_0\|_{L^{\infty}}$, and $\|u_0\|_{H^1}$ such that
    	\begin{align}\label{lem14-1}
    		& \int_{0}^{T}( \|\nabla F\|_{L^p} + \|\nabla \omega\|_{L^p}+ \|\rho \tilde{u}\|_{L^p})^{1+\frac{1}{p}} \mbox{d}t + \int_{0}^{T} ( \|F\|_{L^{\infty}}^{\frac{3}{2}}+ \|\omega\|_{L^{\infty}}^{\frac{3}{2}} \mbox{d}t )\nonumber\\[2mm]
    		&+ \int_{0}^{T}t( \|\nabla F\|_{L^p}^2 + \|\nabla \omega\|_{L^p}^2 + \|\tilde{u}\|^2_{H^1} ) \mbox{d}t \leq C,
    	\end{align}
    	and that
    	\begin{equation}\label{lem14-2}
    		\inf_{(x,t)\in \Omega \times (0,T)} \rho(x,t) \geq C^{-1} \inf_{x\in \Omega } \rho_0 (x).
    	\end{equation}

First, using Lemma \ref{lem12}, the bound for $\|\rho\|_{L^{\infty}}$ from Lemma \ref{lem11}, and Lemma \ref{lem-poincare} to estimate $\|\rho \tilde{u}\|_{L^p}$, we obtain
    	\begin{align}\label{14-1}
    		\|\rho \tilde{u}\|_{L^p} & \leq C \|\rho \tilde{u}\|_{L^2}^{\frac{2(p-1)}{p^2-2}}\|\tilde{u}\|_{H^1}^{\frac{p(p-2)}{p^2-2}}\leq C \|\rho \tilde{u}\|_{L^2} + C \|\rho \tilde{u}\|_{L^2}^{\frac{2(p-1)}{p^2-2}}\|\nabla \tilde{u}\|_{L^2}^{\frac{p(p-2)}{p^2-2}},
    	\end{align}
    	which, together with Lemma \ref{lem13} and \eqref{13-15}, implies that
    	\begin{align}\label{14-2}
    		& \int_{0}^{T} ( \|\rho \tilde{u}\|_{L^p}^{1+\frac{1}{p}} + t \|\tilde{u}\|^2_{H^1} ) \mbox{d}t \nonumber\\[2mm]
    		& \leq C \int_{0}^{T}( \|\sqrt{\rho}\tilde{u}\|_{L^2}^2 + t\|\nabla \tilde{u}\|_{L^2}^2 + t^{-1+\frac{2}{p^3-p^2-2p+2}} )\mbox{d}t \leq C.
    	\end{align}
    	
    	
    	The Gagliardo-Nirenberg inequality, \eqref{5-4}, and Lemma \ref{lem11} then yield
    	\begin{align}\label{14-3}
    		\|F\|_{L^{\infty}} + \|\omega\|_{L^{\infty}} & \leq C(\|F\|_{L^2}+ \|\omega\|_{L^2} + \|F\|_{L^2}^{\frac{p-2}{2(p-1)}}\|\nabla F\|_{L^p}^{\frac{p}{2(p-1)}}+ \|\omega\|_{L^2}^{\frac{p-2}{2(p-1)}}\|\nabla \omega\|_{L^p}^{\frac{p}{2(p-1)}})\nonumber\\[2mm]
    		& \leq C(\|\rho \tilde{u}\|_{L^p}^{\frac{p}{2(p-1)}}+1),
    	\end{align}
    	which, together with \eqref{14-2}, gives \eqref{lem14-1}.
    	
    	Finally, \eqref{lem14-2} is a direct consequence of \eqref{lem14-1} and $\eqref{origin}^1$.

\label{lem15}
    	Assume that \eqref{betagamma} holds. Then, for $q>2$ as in Theorem \ref{thm1}, there is a constant $\tilde{C}$ depending only on $\Omega,T,q,\mu,\beta, \gamma$, $\|b(x)\|_{W^{1,q}}$, $\|\rho_0\|_{W^{1,q}}$, and $\|u_0\|_{H^1}$ such that
    	\begin{align}\label{lem15-1}
    		& \sup_{0 \leq t \leq T} ( \|\rho \|_{W^{1,q}}+ t\|u\|_{H^2}^2 )+ \int_{0}^{T}( \|\nabla^2 u\|_{L^q}^{1+\frac{q}{1}} + t\|\nabla^2 u\|_{L^q}^2+ t\|u_t\|^2_{H^1}) \mbox{d}t \leq \tilde{C}.
    	\end{align}

First, set $\Psi=(\Psi_1, \Psi_2)$, where $\Psi_i := (2\mu +\lambda(\rho))\partial_i \rho(i=1,2)$. It follows from $\eqref{origin}^1$ that $\Psi_i$ satisfies
    	\begin{equation}\label{15-1}
    		\partial_t \Psi_i + ( u \cdot \nabla )\Psi_i + ( 2\mu +\lambda(\rho))\nabla \rho \cdot \partial_i u+ \rho \partial_i F+ \rho \partial_i P +\Psi_i \mbox{div}u=0.
    	\end{equation}
    	
    	For $q>2$, multiplying \eqref{15-1} by $|\Psi|^{q-2}\Psi_i$ and integrating over $\Omega$ gives
    	\begin{align}\label{15-2}
    		& \int_{\Omega} \frac{1}{q} \frac{\partial }{\partial t} |\Psi|^q + \frac{1}{q}(u \cdot \nabla)|\Psi|^q + (2\mu +\lambda(\rho))(\Psi \cdot \nabla)u \cdot \nabla \rho |\Psi|^{q-2}\nonumber\\[2mm]
    		& + \rho \Psi \cdot \nabla F|\Psi|^{q-2}+ \rho \Psi \cdot \nabla P|\Psi|^{q-2} + \mbox{div}u|\Psi|^q \mbox{d}x=0,
    	\end{align}
    	Integrating by parts and using the boundary condition \eqref{boundary1} to eliminate the boundary term, we obtain
    	\begin{equation}\label{15-3}
    		\frac{d}{dt} \|\Psi\|_{L^q} \leq \tilde{C}( 1+\|\nabla u\|_{L^{\infty}} )\|\Psi\|_{L^q} + \tilde{C}\|\nabla F\|_{L^q},
    	\end{equation}
    	where we used the estimates for $\rho$ (Lemma \ref{lem2}).
    	
    	Next, using the standard $L^p$ estimate for the elliptic system with boundary condition \eqref{boundary1}, together with \eqref{14-3} for $\|\mbox{div} u\|_{L^{\infty}}$ and \eqref{5-4} for $\|\nabla F\|_{L^q}$ and $\|\nabla \omega\|_{L^q}$, we obtain
    	\begin{align}\label{15-4}
    		\|\nabla^2 u\|_{L^q} & \leq \tilde{C}( \|\nabla \mbox{div}u\|_{L^q} + \|\nabla \omega\|_{L^q} )\nonumber\\[2mm]
    		& \leq \tilde{C}( \|\nabla(2\mu +\lambda(\rho))\mbox{div}u\|_{L^q} + \|\mbox{div}u\|_{L^{\infty}}\|\nabla \rho\|_{L^q} + \|\nabla \omega\|_{L^q} )\nonumber\\[2mm]
    		& \leq \tilde{C}( \|\mbox{div}u\|_{L^{\infty}} +1)\|\nabla \rho\|_{L^q} + \tilde{C}\|\nabla F\|_{L^q}+ \tilde{C}\|\nabla \omega\|_{L^q}\nonumber\\[2mm]
    		& \leq \tilde{C}(\|\rho \tilde{u}\|_{L^q}+1)\|\nabla \rho\|_{L^q} + \tilde{C}\|\rho \tilde{u}\|_{L^q}.
    	\end{align}
    	
    	Lemma \ref{lem-nablau} and the preceding estimate then give
    	\begin{align}\label{15-5}
    		\|\nabla u\|_{L^{\infty}} & \leq \tilde{C}( \|\mbox{div}u\|_{L^{\infty}} + \|\omega\|_{L^{\infty}} )\log (e+\|\nabla^2 u \|_{L^q}) + \tilde{C}\|\nabla u\|_{L^2} + \tilde{C}\nonumber\\[2mm]
    		& \leq \tilde{C}(1+\|\rho \tilde{u}\|_{L^q})\log (e+\|\nabla \rho\|_{L^q}+ \|\rho \tilde{u}\|_{L^q}) + \tilde{C}.
    	\end{align}
    	
    	Noting that
    	\begin{equation}\label{15-6}
    		2\mu \|\nabla \rho\|_{L^q} \leq \|\Psi\|_{L^q} \leq \tilde{C}\|\nabla \rho\|_{L^q},
    	\end{equation}
    	we substitute \eqref{15-5} into \eqref{15-3} and use \eqref{5-4} to estimate $\|\nabla F\|_{L^q}$, obtaining
    	\begin{equation}\label{15-7}
    		\frac{d}{dt} \log (e+\|\Psi\|_{L^q})= \frac{\frac{d}{dt}\|\Psi\|_{L^q}}{e+\|\Psi\|_{L^q}} \leq \tilde{C}(1+\|\rho \tilde{u}\|_{L^q})\log (e+\|\Psi\|_{L^q}) + \tilde{C}\|\rho \tilde{u}\|_{L^q}^{1+\frac{1}{q}},
    	\end{equation}
    	which, together with Gronwall's inequality, \eqref{5-4}, Lemma \ref{lem14}, and \eqref{15-6}, yields
    	\begin{equation}\label{15-8}
    		\sup_{0 \leq t \leq T}\|\nabla \rho\|_{L^q} \leq \tilde{C}.
    	\end{equation}
    	
    	Combining \eqref{15-4}, \eqref{15-8}, and Lemma \ref{lem14} gives
    	\begin{equation}\label{15-9}
    		\int_{0}^{T}( \|\nabla^2u \|_{L^q}^{1+\frac{1}{q}} + t \|\nabla^2 u\|_{L^q}^2 )\mbox{d}t \leq \tilde{C}.
    	\end{equation}
    	
    	Finally, using Lemma \ref{lem12} for $\|\tilde{u}\|_{H^1}$, \eqref{13-15} for $\|\nabla u\|_{L^4}$, Lemma \ref{lem2} for $\|\nabla \Phi\|_{H^1}\leq \|\rho\|_{L^2}+\|\nabla \Phi\|_{L^2}\leq C$, Lemma \ref{lem11} for $\sup_{0 \leq t \leq T}\|u\|_{H^1}$, Lemma \ref{lem13} for $t\|\nabla \dot{u}\|$, and \eqref{15-9}, we obtain
    	\begin{align}\label{15-10}
    		\int_{0}^{T} t \|u_t\|^2_{H^1} \mbox{d}t & \leq \tilde{C} \int_{0}^{T}t( \|\tilde{u}\|_{H^1}^2 + \|u \cdot \nabla u\|_{H^1}^2 + \|\nabla \Phi\|_{H^1}^2)\mbox{d}t \nonumber\\[2mm]
    		& \leq \tilde{C} \int_{0}^{T}t( 1+ \|\nabla \dot{u}\|_{L^2}^2 + \|\nabla u\|_{L^4}^4 + \|u\|^2_{H^1}\|\nabla u\|_{L^q}^2 )\mbox{d}t \leq \tilde{C}.
    	\end{align}
    	
    	Using Lemma \ref{lem11} for $\sup_{0 \leq t \leq T}\|\nabla u\|_{L^2}$, \eqref{5-4} for $\|\nabla F\|_{L^2} + \|\nabla \omega\|_{L^2}$, and \eqref{15-8}, we obtain
    	\begin{align}\label{15-11}
    		\|\nabla^2 u\|_{L^2} & \leq \tilde{C}( \|\nabla \mbox{div}u\|_{L^2} + \|\nabla \omega\|_{L^2} )\nonumber\\[2mm]
    		& \leq \tilde{C}( \|\nabla (2\mu +\lambda(\rho))\mbox{div}u\|_{L^2}+ \|\mbox{div}u\|_{L^{\frac{2q}{q-2}}}\|\nabla \rho\|_{L^q} + \|\nabla \omega\|_{L^2} )\nonumber\\[2mm]
    		& \leq \tilde{C}\|\nabla F\|_{L^2} + \tilde{C}\|\nabla \omega\|_{L^2} + \tilde{C} + \tilde{C}\|\nabla u\|_{L^2}^{\frac{q-2}{q}}\|\nabla^2 u\|_{L^2}^{\frac{2}{q}}\nonumber\\[2mm]
    		& \leq \frac{1}{2}\|\nabla^2u\|_{L^2} + \tilde{C} \|\rho \tilde{u}\|_{L^2} + \tilde{C},
    	\end{align}
    	which, together with Lemma \ref{lem13}, gives
    	\begin{equation}\label{15-12}
    		\sup_{0 \leq t \leq T}t \|\nabla^2 u\|^2_{L^2}\leq \tilde{C}.
    	\end{equation}
    	
    	Combining the preceding estimates with Lemma \ref{lem11} yields \eqref{lem15-1} and completes the proof of Lemma \ref{lem15}.

The standard local existence result, Lemma \ref{lem-localexistence}, ensures that the problem \eqref{origin}-\eqref{boundary2} with initial data $(\rho_0,u_0,\Phi_0)$ has a unique local solution $(\rho,u,\nabla \Phi)$ defined up to a positive time $T_0$, which may depend on $\inf_{x\in \Omega }\rho_0(x)$, and satisfying \eqref{localexistence} and \eqref{localinf}. We set
    	
    	\begin{equation}\label{p1-1}
    		T^*= \sup\{ T| \sup_{0 \leq t \leq T} (\|(\rho,u)\|_{H^2}+\|\nabla \Phi\|_{H^1}) < \infty \}.
    	\end{equation}
    	
    	Clearly, $T^* \geq T_0$. If $T^*< \infty$, we claim that there exists a positive constant $\hat{C}$ which may depend on $b(x)$, $T^*$ and $\inf_{x\in \Omega } \rho_0(x)$ such that, for all $0<T<T^*$,
    	\begin{equation}\label{p1-2}
    		\sup_{0 \leq t \leq T}\|\rho\|_{H^2} \leq \hat{C}.
    	\end{equation}
    	
    	This together with \eqref{lem15-1} contradicts \eqref{p1-1}. Thus, we have
    	\begin{equation}\label{p1-3}
    		T^*=\infty.
    	\end{equation}
    	
    	It remains to prove \eqref{p1-2}. First, standard calculations and \eqref{lem15-1} imply that, for any $T \in (0,T^*)$,
    	\begin{equation}\label{p1-4}
    		\inf_{(x,t)\in \Omega \times (0,T)} \rho(x,t) \geq \inf_{x\in \Omega } \rho_0(x) \exp^{-\int_{0}^{T}\|\mbox{div}u\|_{L^{\infty}}\mbox{d}t} \geq \hat{C}^{-1},
    	\end{equation}
    	Here and below, $\hat{C}$ denotes a generic positive constant depending on $\inf_{x\in \Omega } \rho_0(x)$ and $T^*$ but independent of $T$. In view of \eqref{initialvalue}, we define
    	\begin{equation}\label{p1-5}
    		\sqrt{\rho}\tilde{u}(x,t=0) = \rho_0^{-\frac{1}{2}}( \mu \Delta u_0+ \nabla ((\mu + \lambda(\rho_0))\mbox{div}u_0)- \nabla P(\rho_0)).
    	\end{equation}
    	
    	Integrating \eqref{13-16} with respect to $t$ over $(0,T)$ and using \eqref{initialvalue}, Lemma \ref{lem11}, and \eqref{p1-5}, we obtain
    	\begin{equation}\label{p1-6}
    		\sup_{0 \leq t \leq T} \int_{\Omega} \rho |\tilde{u}|^2 \mbox{d}x + \int_{0}^{T} \|\nabla \dot{u}\|^2_{L^2}\mbox{d}t \leq \hat{C}.
    	\end{equation}
    	
    	
    	Combining this with \eqref{15-11} for $\|\nabla^2 u\|_{L^2}$ and \eqref{lem15-1}, and recalling that $\Delta F= \mbox{div}( \rho \tilde{u})$ and $\mu \Delta \omega= \nabla^{\bot} \cdot (\rho \tilde{u})$, we obtain
    	\begin{align}\label{p1-7}
    		& \sup_{0 \leq t \leq T}( \|\nabla^2 u\|_{L^2} + \|\nabla F\|_{L^2}+ \|\nabla \omega\|_{L^2}) + \int_{0}^{T}( \|\nabla^2 F\|_{L^2}^2 + \|\nabla^2 \omega\|_{L^2}^2 )\mbox{d}t \nonumber\\[2mm]
    		& \leq \hat{C} \sup_{0 \leq t \leq T} \|\rho \tilde{u}\|_{L^2} + \hat{C}\int_{0}^{T} \|\nabla(\rho \tilde{u})\|_{L^2}^2 \mbox{d}t \nonumber\\[2mm]
    		& \leq \hat{C} + \hat{C}\int_{0}^{T}( \|\nabla \rho\|_{L^q}^2\|\tilde{u}\|_{L^{\frac{2q}{q-2}}}^2 + \|\nabla \tilde{u}\|_{L^2}^2 )\mbox{d}t \leq \hat{C} + \hat{C}\int_{0}^{T} \|\tilde{u}\|_{H^1}^2\mbox{d}t \leq \hat{C},
    	\end{align}
    	where we have used \eqref{5-3} with $k=1$ and $p=2$. The additional terms involving $u$ and $\tilde{u}$ are controlled by \eqref{p1-6}, Lemma \ref{lem15}, and \eqref{15-11}.
    	
    	
    	Next, applying $\nabla$ to \eqref{15-1} gives
    	\begin{equation}
    		\partial_t \Psi_i + ( u \cdot \nabla )\Psi_i + ( 2\mu +\lambda(\rho))\nabla \rho \cdot \partial_i u+ \rho \partial_i F+ \rho \partial_i P +\Psi_i \mbox{div}u=0,
    	\end{equation}
    	multiplying the resulting identity by $\nabla \Psi_i$, integrating by parts, and using \eqref{p1-4} and \eqref{p1-7}, we obtain
    	\begin{align}\label{p1-8}
    		\frac{d}{dt}\|\nabla \Psi\|_{L^2} &\leq \hat{C}(1+\|\nabla u\|_{L^{\infty}})( 1+\|\nabla \Psi\|_{L^2}+\|\nabla \rho\|_{L^4}^2+ \|\nabla^2 \rho\|_{L^2} )\nonumber\\[2mm]
    		&+ \hat{C}\| |\nabla \rho||\nabla^2u|\|_{L^2} + \hat{C}\| |\nabla \rho||\nabla F|\|_{L^2} + \hat{C}\|\nabla^2 F\|_{L^2}.
    	\end{align}
    	
    	The identity $\Psi_i=(2\mu +\lambda(\rho))\partial_i\rho$, together with Lemma \ref{lem15}, yields
    	\begin{align}\label{p1-9}
    		\|\nabla^2 \rho\|_{L^2}+\|\nabla \rho\|_{L^4}^2 & \leq \hat{C}\|\nabla \Psi\|_{L^2}+ \hat{C}\|\nabla \rho\|_{L^4}^2 \leq \hat{C}\|\nabla \Psi\|_{L^2}+ \hat{C} \|\nabla \rho\|_{L^{l}}^{\frac{l}{2}}\|\nabla^2 \rho\|_{L^2}^{\frac{4-l}{2}} \nonumber\\[2mm]
    		& \leq \hat{C}\|\nabla\Psi\|_{L^2} + \frac{1}{2}\|\nabla^2 \rho\|_{L^2}+\hat{C},
    	\end{align}
    	where we have chosen $l=\min\{4,q\}$ and used Poincar\'{e}'s inequality (Lemma \ref{lem-poincare}).
    	
    	
    	H$\ddot{o}$lder's inequality, Lemma \ref{lem-poincare}, Lemma \ref{lem15}, and \eqref{p1-7} then give
    	\begin{align}\label{p1-10}
    		\| |\nabla \rho||\nabla^2u|\|_{L^2} + \| |\nabla \rho||\nabla F|\|_{L^2} &\leq \hat{C}\|\nabla \rho\|_{L^q}\|\nabla^2 u\|_{L^2}^{1-\frac{2}{q}}\|\nabla^3 u\|_{L^2}^{\frac{2}{q}} + \hat{C}\|\nabla \rho\|_{L^q}\|\nabla F\|_{L^2}^{1-\frac{2}{q}}\|\nabla^2 F\|_{L^2}^{\frac{2}{q}}\nonumber\\[2mm]
    		& \leq \hat{C}(\epsilon) \epsilon\|\nabla^3 u \|_{L^2} + \hat{C}\|\nabla^2 F\|_{L^2}.
    	\end{align}
    	
    	Moreover, the $L^2$ estimate for the elliptic system gives
    	\begin{align}\label{p1-11}
    		\|\nabla^3 u\|_{L^2} &\leq \hat{C}\|\nabla^2 \mbox{div} u\|_{L^2}+ \hat{C}\|\nabla^2 \omega\|_{L^2}\nonumber\\[2mm]
    		& \leq \hat{C}\|\nabla^2 F\|_{L^2} + \hat{C}\|\nabla^2 \rho\|_{L^2}+ \hat{C}\|\nabla \rho\|_{L^4}^2+ \hat{C}\||\nabla \rho||\nabla^2 u|\|_{L^2} \nonumber\\[2mm]
    		&+ \hat{C}( \|\nabla^2 \rho\|_{L^2} + \|\nabla \rho\|_{L^4}^2 )\|\nabla u\|_{L^{\infty}} + \hat{C}\|\nabla^2 \omega\|_{L^2}. 
    	\end{align}
    	
    	Substituting this and \eqref{p1-9} into \eqref{p1-10} shows
    	\begin{align}\label{p1-12}
    		& \|\nabla^2 \rho\|_{L^2}+\|\nabla \rho\|_{L^4}^2 \leq \hat{C}\|\nabla \Psi\|_{L^2}+ \hat{C}\|\nabla \rho\|_{L^4}^2\nonumber\\[2mm]
    		& \leq \hat{C}\|\nabla^2 F\|_{L^2} + \hat{C}\|\nabla^2 \omega\|_{L^2} + \hat{C}(1+\|\nabla \Psi\|_{L^2})(1+\|\nabla u\|_{L^{\infty}}),
    	\end{align}
    	which together with \eqref{p1-8} gives
    	\begin{equation}\label{p1-13}
    		\frac{d}{dt}\|\nabla \Psi\|_{L^2} \leq \hat{C}\|\nabla^2 F\|_{L^2} + \hat{C}\|\nabla^2 \omega\|_{L^2} + \hat{C}(1+\|\nabla \Psi\|_{L^2})(1+\|\nabla u\|_{L^{\infty}}).
    	\end{equation}
    	
    	This combined with \eqref{p1-7} and Gronwall's inequality yields
    	\begin{equation}\label{p1-14}
    		\sup_{0 \leq t \leq T} \|\nabla \Psi\|_{L^2} \leq \hat{C},
    	\end{equation}
    	which, together with \eqref{p1-9}, implies \eqref{p1-2}. To complete the proof of Proposition \ref{prop1}, we combine the preceding estimates with the relation between $\rho$ and $\Phi$, namely,
    	\begin{equation}\label{p1-15}
    		\Delta \Phi = \rho - b(x),
    	\end{equation}
    	where $b(x) \in H^2$, and apply standard Neumann elliptic regularity with the boundary condition $(\nabla \Phi \cdot n)|_{\partial \Omega}=0$ to obtain
    	\begin{equation}\label{p1-16}
    		\sup_{0 \leq t \leq T}\|\nabla \Phi\|_{H^3}\leq C\sup_{0 \leq t \leq T}\|\Delta \Phi\|_{H^2} \leq C\sup_{0 \leq t \leq T}(\|\rho\|_{H^2}+\|b(x)\|_{H^2}) \leq \hat{C}.
    	\end{equation}
